  function hoiXN(tieuDe, chiTiet, nutOk, tuy) {
    tuy = tuy || {};
    if (!tuy.bao) return Promise.resolve(true);
    return new Promise(xong => {
      const nen = $('nenHoi'), khung = $('hoiKhung'), ok = $('hoiOk'), huy = $('hoiHuy'), truoc = document.activeElement;
      $('hoiTieuDe').textContent = tieuDe; $('hoiChiTiet').textContent = chiTiet || '';
      ok.textContent = nutOk || (tuy.bao ? 'Đóng' : 'Đồng ý'); huy.textContent = tuy.nutHuy || 'Hủy';
      khung.classList.toggle('nguy', !!tuy.nguy); khung.classList.toggle('bao', !!tuy.bao);
      const dong = kq => { nen.classList.remove('mo'); ok.onclick = huy.onclick = nen.onclick = null; document.removeEventListener('keydown', phim, true); try { truoc && truoc.focus && truoc.focus(); } catch (e) {} xong(kq); };
      const phim = e => { if (e.key === 'Escape') { e.preventDefault(); dong(!!tuy.bao); } };
      ok.onclick = () => dong(true); huy.onclick = () => dong(false);
      nen.onclick = e => { if (e.target === nen) dong(!!tuy.bao); };
      document.addEventListener('keydown', phim, true);
      nen.classList.add('mo'); setTimeout(() => (tuy.nguy ? huy : ok).focus(), 30);
    });
  }
